// icon-data.json -> ../roblox-game/game-src/client/IconData.luau
// Base64 RGBA blobs embedded as a Luau module; IconViz decodes at runtime.
import fs from 'node:fs';
import path from 'node:path';

const DIR = path.dirname(new URL(import.meta.url).pathname);
const data = JSON.parse(fs.readFileSync(path.join(DIR, 'icon-data.json'), 'utf8'));

let lua = `--!strict
-- GENERATED by roblox/gen-icons-luau.mjs — do not edit.
-- 48x48 RGBA ticket icons rasterized from the web game's src/ui/icons.ts.
return {
`;
for (const [key, icon] of Object.entries(data)) {
  lua += `\t["${key}"] = { w = ${icon.w}, h = ${icon.h}, rgba = "${icon.rgba}" },\n`;
}
lua += '}\n';

const out = path.join(DIR, '../roblox-game/game-src/client/IconData.luau');
fs.writeFileSync(out, lua);
console.error(`wrote IconData.luau (${Object.keys(data).length} icons, ${(lua.length / 1024).toFixed(0)}KB)`);
